Python: recoverable streaming pattern:
from redwood import Client, RecoverableStreamError
client = Client()
try:
    for chunk in client.stream_generate(...):
        handle_chunk(chunk)
except RecoverableStreamError as e:
    # e.stream_resume_token is opaque; SDK will use it for one automated resume attempt
    if e.retryable:
        client.stream_generate(resume_token=e.stream_resume_token)
    else:
        raise
TypeScript: idempotent retry helper example:
import { RedwoodClient, SDKError } from '@redwood/sdk'
const client = new RedwoodClient()
async function callWithIdempotentRetry() {
  try {
    return await client.generate({ idempotencyKey: 'user-123', ... })
  } catch (err) {
    const sdkErr = err as SDKError
    if (sdkErr.code === 'TransientNetworkError' && sdkErr.hints.includes('retry')) {
      // exponential backoff (helper baked into SDK will do this)
      return client.generate({ idempotencyKey: 'user-123' })
    }
    throw err
  }
}
Go: fallback to cheaper model on latency spike:
resp, err := client.Generate(ctx, &GenerateParams{Model: "rwdl-large"})
if err != nil {
  if sdkErr, ok := err.(redwood.SDKError); ok && sdkErr.Code == "CapacityExhausted" {
    // fallback
    resp, err = client.Generate(ctx, &GenerateParams{Model: "rwdl-small"})
  }
}
